import { Router } from 'express';
import { storage } from '../services/storage.js';
import { GitHubService } from '../services/github.js';
import { detectProjectTechnologies } from '../services/projectDetector.js';
import { scanRepositoryHealth } from '../scanners/healthScanner.js';
import { scanSecrets } from '../scanners/secretScanner.js';
import { scanDependencies } from '../scanners/dependencyScanner.js';
import { scanAccessibility } from '../scanners/accessibilityScanner.js';
import { calculateTransparentScores } from '../scoring/scoreCalculator.js';
export const prRouter = Router();
// POST /api/pr/create - Option A: creates branch, commits fixes, opens PR
prRouter.post('/pr/create', async (req, res) => {
    const { scanId, baseBranch, title, patches } = req.body;
    if (!scanId || !Array.isArray(patches) || patches.length === 0) {
        res.status(400).json({ error: 'scanId and an array of patches to apply are required.' });
        return;
    }
    const report = storage.getReport(scanId);
    if (!report) {
        res.status(404).json({ error: `Scan report with ID "${scanId}" not found.` });
        return;
    }
    try {
        const { owner, name: repo } = report.repository;
        const isSynthetic = !!report.isSyntheticTest;
        const targetBaseBranch = baseBranch || report.repository.selectedBranch || report.repository.defaultBranch;
        // Verify token presence for non-synthetic repositories
        const { getSettings } = await import('../config.js');
        const settings = getSettings();
        const token = settings.githubToken || process.env.GITHUB_TOKEN;
        if (!isSynthetic && (!token || !token.trim())) {
            res.status(401).json({
                error: 'GitHub authorization required: A GitHub Personal Access Token (PAT) with "repo" write scope is required to create a repair branch and open a Pull Request. Please configure your token in Settings.',
            });
            return;
        }
        // 1. Generate unique dedicated repair branch name
        const uniqueId = Math.random().toString(36).substring(2, 8);
        const repairBranchName = `repo-doctor/health-fixes-${uniqueId}`;
        // 2. Create the repair branch pointing to base branch SHA (never push directly to base branch)
        await GitHubService.createRepairBranch(owner, repo, repairBranchName, targetBaseBranch, isSynthetic);
        // 3. Commit approved file changes
        const filesToCommit = patches.map((p) => ({
            path: p.filePath,
            content: p.proposedContent,
            message: `fix(repo-doctor): ${p.explanation || `address finding ${p.findingId}`}`,
        }));
        const commitSha = await GitHubService.commitFiles(owner, repo, repairBranchName, filesToCommit, 'chore(repo-doctor): apply automated health & security remediations', isSynthetic);
        // 4. Construct PR description
        const prTitle = title || `[Repo Doctor] Automated Repository Health & Security Fixes`;
        const appliedFindingIds = patches.map((p) => p.findingId);
        const prBody = `## 🩺 Repo Doctor Automated Repair (Option A)

This Pull Request was generated by **Repo Doctor** to address technical debt, missing documentation, security risks, and accessibility issues detected during repository diagnosis.

### 📋 Addressed Findings (${appliedFindingIds.length})
${patches
            .map((p, idx) => `${idx + 1}. **${p.filePath}**: ${p.explanation || 'Applied proposed fix'}`)
            .join('\n')}

### 🛡️ Safety & Verification
- Branch: \`${repairBranchName}\` created safely from \`${targetBaseBranch}\`.
- No force pushes or history rewrites were performed.
- All secrets are redacted or referenced via environment templates.
- **Workflow**: Per Option A, please review the diffs and merge this Pull Request manually on GitHub. Repo Doctor can then rescan the repository to verify score improvements.

---
*Generated automatically by [Repo Doctor](https://github.com/devf8rge)*`;
        // 5. Open real GitHub Pull Request
        const prResult = await GitHubService.createPullRequest(owner, repo, repairBranchName, targetBaseBranch, prTitle, prBody, isSynthetic);
        const result = {
            success: true,
            prUrl: prResult.prUrl,
            prNumber: prResult.prNumber,
            branchName: repairBranchName,
            baseBranch: targetBaseBranch,
            title: prTitle,
            body: prBody,
            commitSha,
            changedFiles: patches.map((p) => p.filePath),
            appliedFindingIds,
            createdAt: new Date().toISOString(),
        };
        res.json(result);
    }
    catch (err) {
        console.error('PR creation error:', err);
        res.status(500).json({
            error: err.message || 'Failed to create repair branch and open Pull Request.',
        });
    }
});
// GET /api/pr/status - Checks PR merge status and CI workflow runs
prRouter.get('/pr/status', async (req, res) => {
    const { owner, repo, prNumber, branch, isSynthetic } = req.query;
    if (!owner || !repo || !prNumber) {
        res.status(400).json({ error: 'owner, repo, and prNumber query parameters are required.' });
        return;
    }
    try {
        const isSynth = isSynthetic === 'true';
        const num = parseInt(prNumber, 10);
        const prStatus = await GitHubService.getPullRequestStatus(owner, repo, num, isSynth);
        const targetBranch = branch || 'main';
        const ciStatus = await GitHubService.getWorkflowRuns(owner, repo, targetBranch, isSynth);
        res.json({
            prNumber: num,
            state: prStatus.state,
            isMerged: prStatus.isMerged,
            mergedAt: prStatus.mergedAt,
            ciStatus,
        });
    }
    catch (err) {
        console.error('PR status check error:', err);
        res.status(500).json({ error: err.message || 'Failed to check PR status.' });
    }
});
// POST /api/pr/rescan - Post-merge verification and Before-vs-After comparison
prRouter.post('/pr/rescan', async (req, res) => {
    const { previousScanId, branch } = req.body;
    if (!previousScanId) {
        res.status(400).json({ error: 'previousScanId is required for before-and-after comparison.' });
        return;
    }
    const baselineReport = storage.getReport(previousScanId);
    if (!baselineReport) {
        res.status(404).json({ error: `Baseline scan report "${previousScanId}" not found.` });
        return;
    }
    try {
        const { owner, name: repo, url } = baselineReport.repository;
        const isSynthetic = !!baselineReport.isSyntheticTest;
        const targetBranch = branch || baselineReport.repository.selectedBranch;
        // In synthetic benchmark mode, simulate the user's manual GitHub merge of the repair branch into the target base branch
        if (isSynthetic) {
            const { TKS_SYNTHETIC_REPO } = await import('../fixtures/tksFixture.js');
            const synthBranches = TKS_SYNTHETIC_REPO.branches;
            const latestRepairBranch = synthBranches
                .filter((b) => b.startsWith('repo-doctor/health-fixes-'))
                .slice(-1)[0];
            if (latestRepairBranch && TKS_SYNTHETIC_REPO.files[latestRepairBranch]) {
                TKS_SYNTHETIC_REPO.files[targetBranch] = {
                    ...(TKS_SYNTHETIC_REPO.files[targetBranch] || {}),
                    ...TKS_SYNTHETIC_REPO.files[latestRepairBranch],
                };
            }
        }
        // Rescan repository tree
        const tree = await GitHubService.getTree(owner, repo, targetBranch, isSynthetic);
        const contentCache = new Map();
        const getFileContent = async (filePath) => {
            if (contentCache.has(filePath))
                return contentCache.get(filePath);
            const content = await GitHubService.getFileContent(owner, repo, filePath, targetBranch, isSynthetic);
            contentCache.set(filePath, content);
            return content;
        };
        const projectAnalysis = detectProjectTechnologies(tree);
        const [healthFindings, secretFindings, depFindings, a11yFindings] = await Promise.all([
            scanRepositoryHealth(tree, projectAnalysis, owner, repo, targetBranch, getFileContent),
            scanSecrets(tree, owner, repo, targetBranch, getFileContent),
            scanDependencies(tree, owner, repo, targetBranch, getFileContent),
            scanAccessibility(tree, owner, repo, targetBranch, getFileContent),
        ]);
        const currentFindings = [
            ...healthFindings,
            ...secretFindings,
            ...depFindings,
            ...a11yFindings,
        ];
        const { overallScore, categoryScores } = calculateTransparentScores(currentFindings);
        const currentScanId = `scan_rescan_${Date.now()}`;
        // Determine resolved vs persistent vs new findings
        const currentRuleAndPaths = new Set(currentFindings.map((f) => `${f.ruleId}:${f.filePath}`));
        const baselineRuleAndPaths = new Set(baselineReport.findings.map((f) => `${f.ruleId}:${f.filePath}`));
        const resolvedFindings = baselineReport.findings.filter((f) => !currentRuleAndPaths.has(`${f.ruleId}:${f.filePath}`));
        const persistentFindings = currentFindings.filter((f) => baselineRuleAndPaths.has(`${f.ruleId}:${f.filePath}`));
        const newFindings = currentFindings.filter((f) => !baselineRuleAndPaths.has(`${f.ruleId}:${f.filePath}`));
        // Compute category score deltas
        const categoryScoreDeltas = {};
        for (const cat of Object.keys(categoryScores)) {
            const before = baselineReport.categoryScores[cat]?.score || 0;
            const after = categoryScores[cat]?.score || 0;
            categoryScoreDeltas[cat] = {
                before,
                after,
                delta: after - before,
            };
        }
        // Check CI status
        const ciStatus = await GitHubService.getWorkflowRuns(owner, repo, targetBranch, isSynthetic);
        const comparison = {
            previousScanId,
            currentScanId,
            timestamp: new Date().toISOString(),
            repository: `${owner}/${repo}`,
            branch: targetBranch,
            isMerged: true,
            scoreBefore: baselineReport.overallScore,
            scoreAfter: overallScore,
            scoreDelta: overallScore - baselineReport.overallScore,
            categoryScoreDeltas,
            resolvedFindings,
            persistentFindings,
            newFindings,
            ciStatus,
        };
        storage.saveComparison(comparison);
        res.json(comparison);
    }
    catch (err) {
        console.error('Rescan error:', err);
        res.status(500).json({ error: err.message || 'Failed to rescan repository.' });
    }
});
